import java.util.ArrayList;
import java.util.List;

class Patient {
    private String name;
    public Patient(String name) { this.name = name; }
    public String getName() { return name; }
}

class Doctor {
    private String name;
    private String specialty;
    // 1-to-Many Unidirectional Association
    private List<Patient> patients = new ArrayList<>();

    public Doctor(String name, String specialty) {
        this.name = name;
        this.specialty = specialty;
    }

    public void admitPatient(Patient p) {
        patients.add(p);
    }

    public void conductRounds() {
        System.out.println("Dr. " + name + " (" + specialty + ") visiting patients:");
        for (Patient p : patients) {
            System.out.println(" - Checking chart for: " + p.getName());
        }
    }
}

public class AssociationDemo {
    public static void main(String[] args) {
        Patient p1 = new Patient("Marcus");
        Patient p2 = new Patient("Elena");

        Doctor doc = new Doctor("Sarah Stone", "Cardiology");
        doc.admitPatient(p1);
        doc.admitPatient(p2);

        doc.conductRounds();
    }
}

