class Passport {
    private String passportNumber;
    private Person owner; // Back-reference

    public Passport(String passportNumber) {
        this.passportNumber = passportNumber;
    }

    public String getPassportNumber() { return passportNumber; }
    public Person getOwner() { return owner; }
    void setOwnerInternal(Person p) { this.owner = p; }
}

class Person {
    private String name;
    private Passport passport;

    public Person(String name) { this.name = name; }
    public String getName() { return name; }
    public Passport getPassport() { return passport; }

    // Synchronized bidirectional assignment
    public void assignPassport(Passport p) {
        this.passport = p;
        if (p != null) {
            p.setOwnerInternal(this);
        }
    }
}

public class BidirectionalDemo {
    public static void main(String[] args) {
        Person citizen = new Person("John Doe");
        Passport doc = new Passport("US-887410");

        citizen.assignPassport(doc);
        System.out.println(citizen.getName() + " holds: " + citizen.getPassport().getPassportNumber());
        System.out.println("Passport " + doc.getPassportNumber() + " belongs to: " + doc.getOwner().getName());
    }
}

