class Classroom {
    private String roomNumber;
    private Teacher teacher;
    public Classroom(String roomNumber) {
        this.roomNumber = roomNumber;
    }
    public String getRoomNumber() { return roomNumber; }
    public Teacher getTeacher() { return teacher; }
    void setTeacherInternal(Teacher t) { this.teacher = t; }
}

class Teacher {
    private String teacherName;
    private Classroom assignedRoom;
    public Teacher(String teacherName) {
        this.teacherName = teacherName;
    }
    public String getTeacherName() { return teacherName; }
    public Classroom getAssignedRoom() { return assignedRoom; }
    public void assignClassroom(Classroom room) {
        this.assignedRoom = room;
        if (room != null) {
            room.setTeacherInternal(this);
        }
    }
}

public class SchoolApp {
    public static void main(String[] args) {
        Teacher t = new Teacher("Prof. Davis");
        Classroom r = new Classroom("Room-302");
        t.assignClassroom(r);
        System.out.println("Teacher " + t.getTeacherName() + " is in " + t.getAssignedRoom().getRoomNumber());
        System.out.println("Classroom " + r.getRoomNumber() + " is taught by " + r.getTeacher().getTeacherName());
    }
}

import java.util.ArrayList;
import java.util.List;

class Doctor {
    private String doctorId;
    private String specialty;
    public Doctor(String doctorId, String specialty) {
        this.doctorId = doctorId;
        this.specialty = specialty;
    }
    public String getInfo() {
        return "Dr. ID: " + doctorId + " [" + specialty + "]";
    }
}

class ShiftSchedule {
    private String shiftDate;
    private List<Doctor> onCallDoctors = new ArrayList<>();
    public ShiftSchedule(String shiftDate) {
        this.shiftDate = shiftDate;
    }
    public void assignDoctor(Doctor doc) {
        onCallDoctors.add(doc);
    }
    public void printRoster() {
        System.out.println("=== Shift: " + shiftDate + " ===");
        for (Doctor doc : onCallDoctors) {
            System.out.println(" * " + doc.getInfo());
        }
    }
}

public class HospitalApp {
    public static void main(String[] args) {
        ShiftSchedule shift = new ShiftSchedule("2026-10-15");
        shift.assignDoctor(new Doctor("DOC-101", "Trauma"));
        shift.assignDoctor(new Doctor("DOC-102", "Neurology"));
        shift.printRoster();
    }
}

