class Enrollment {
    private Student student;
    private Course course;
    private String grade;

    public Enrollment(Student student, Course course, String grade) {
        this.student = student;
        this.course = course;
        this.grade = grade;
    }

    public void printRecord() {
        System.out.println("[Enrollment] " + student.getName() + " enrolled in " + course.getCourseCode() + " (" + course.getTitle() + ") -> Grade: " + grade);
    }
}

public class UniversityApp {
    public static void main(String[] args) {
        Student alice = new Student("S01", "Alice");
        Course cs101 = new Course("CS101", "Intro to CS");
        Course cs102 = new Course("CS102", "Data Structures");

        Enrollment e1 = new Enrollment(alice, cs101, "A");
        Enrollment e2 = new Enrollment(alice, cs102, "A-");

        e1.printRecord();
        e2.printRecord();
    }
}
